def rows(name: str) -> list[dict[str, str]]:
    with open(DATA / name, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


us = rows("tb_us.csv")
print("US dr", sum(D(r["debit"]) for r in us), "cr", sum(D(r["credit"]) for r in us))
uk = rows("tb_uk.csv")
print("UK signed sum", sum(D(r["balance"]) for r in uk))
ind = rows("tb_in.csv")
dr = sum(D(r["amount"]) for r in ind if r["dr_cr"] == "Dr")
cr = sum(D(r["amount"]) for r in ind if r["dr_cr"] == "Cr")
print("IN dr", dr, "cr", cr)

uk_codes = {r["nominal_code"] for r in uk}
map_uk = {r["local_code"]: r["group_code"] for r in rows("map_uk.csv")}
print("UK codes with no mapping:", sorted(uk_codes - set(map_uk)), "| mapping rows not in TB:", sorted(set(map_uk) - uk_codes))
coa = {r["account_code"]: r for r in rows("group_coa.csv")}
for r in uk:
    g = map_uk[r["nominal_code"]]
    bal = D(r["balance"])
    nb = coa[g]["normal_balance"]
    odd = (nb == "Credit" and bal > 0 and coa[g]["account_type"] in ("Revenue", "Liability", "Equity")) or (
        nb == "Debit" and bal < 0 and coa[g]["account_type"] in ("Expense", "Asset") and r["nominal_code"] != "0031")
    if odd:
        print("  sign vs nature oddity:", r["nominal_code"], r["description"], bal, "->", g, coa[g]["account_name"], coa[g]["account_type"])
print("  2310 maps to", map_uk["2310"], coa[map_uk["2310"]]["account_name"], coa[map_uk["2310"]]["account_type"])

inm = {r["local_code"]: r["group_code"] for r in rows("map_in.csv")}
print("IN ledger codes unmapped:", sorted({r["ledger_code"] for r in ind} - set(inm)))

pl = rows("in_pl_monthly.csv")
tbin = {r["ledger_code"]: D(r["amount"]) for r in ind}
for code in sorted({r["ledger_code"] for r in pl}):
    tot = sum(D(r["amount"]) for r in pl if r["ledger_code"] == code)
    h1 = sum(D(r["amount"]) for r in pl if r["ledger_code"] == code and r["month"] <= "2024-06")
    print(f"  {code}: monthly sum {tot} vs TB {tbin[code]} equal={tot == tbin[code]}; Apr-Jun {h1}; Jul-Dec {tot - h1}")


def net(period_ok) -> D:
    total = D(0)
    for r in pl:
        if period_ok(r["month"]):
            amt = D(r["amount"])
            total += amt if r["dr_cr"] == "Cr" else -amt
    return total


print("IN profit Apr-Jun", net(lambda m: m <= "2024-06"), "Jul-Dec", net(lambda m: m >= "2024-07"), "Apr-Dec", net(lambda m: True))

fx = {(r["base_currency"], r["quote_currency"], r["rate_type"]): D(r["rate"]) for r in rows("fx_rates.csv")}
gbpusd_close = fx[("GBP", "USD", "closing")]
usdinr_close = fx[("USD", "INR", "closing")]
print("GBP/INR closing derived", gbpusd_close * usdinr_close, "| SGD rate types present:", [k[2] for k in fx if k[1] == "SGD"])
sgd = next(r for r in uk if r["nominal_code"] == "1210")
print("SGD 40000 booked 23010 -> implied SGD per GBP", D(sgd["txn_amount"]) / D(sgd["balance"]))
dueto = next(r for r in uk if r["nominal_code"] == "2150")
print("2150 USD 629840 booked", dueto["balance"], "implied USD per GBP", D(dueto["txn_amount"]) / D(dueto["balance"]))
print("2150 at closing", (D("629840") / gbpusd_close).quantize(D("0.01")), "| US receivable 640000 at closing", (D("640000") / gbpusd_close).quantize(D("0.01")))
print("IC diff (US recv at closing - UK payable booked)", (D("640000") / gbpusd_close - D("490707.72")).quantize(D("0.01")))

ic = rows("intercompany.csv")
for side in ("US", "UK"):
    print("IC", side, "booked total", sum(D(r["booked_amount"]) for r in ic if r["reporting_entity"] == side), "n", sum(1 for r in ic if r["reporting_entity"] == side))
print("IC docs only on US side:", sorted({r["doc_ref"] for r in ic if r["reporting_entity"] == "US"} - {r["doc_ref"] for r in ic if r["reporting_entity"] == "UK"}))
for r in ic:
    if r["reporting_entity"] == "UK":
        print("  UK booked", r["doc_ref"], r["doc_date"], "implied USD per GBP", (D(r["doc_amount"]) / D(r["booked_amount"])).quantize(D("0.0001")))

sub = rows("subledger_controls.csv")
tb_ar = {"US": D("3120000"), "UK": D("1985000"), "IN": tbin["IN-AR"]}
tb_ap = {"US": D("1665000"), "UK": D("1210000"), "IN": tbin["IN-AP"]}
for r in sub:
    book = (tb_ar if "receivable" in r["ledger"] else tb_ap)[r["entity_id"]]
    print("sub-ledger", r["entity_id"], r["ledger"], r["control_total"], "TB", book, "diff", book - D(r["control_total"]))

consideration_inr = D("690000000")
net_assets = D("678000000")
print("goodwill INR", consideration_inr - D("0.8") * net_assets, "| US investment USD", (consideration_inr / fx[("USD", "INR", "spot")]).quantize(D("0.01")))
print("goodwill GBP at closing", ((consideration_inr - D("0.8") * net_assets) / (gbpusd_close * usdinr_close)).quantize(D("0.01")))

je = json.loads((DATA / "adjustments.json").read_text(encoding="utf-8"))["entries"]
accounts_in = set(inm) | {r["local_code"] for r in rows("map_uk.csv")} | set(coa)
for e in je:
    d = sum(D(line["debit"]) for line in e["lines"])
    c = sum(D(line["credit"]) for line in e["lines"])
    flags = []
    if d != c:
        flags.append(f"UNBALANCED dr {d} cr {c}")
    if not ("2024-01-01" <= e["date"] <= "2024-12-31"):
        flags.append("date outside FY2024")
    known = {"US": set(coa), "UK": {r["nominal_code"] for r in uk}, "IN": set(inm)}[e["entity"]]
    for line in e["lines"]:
        if line["account"] not in known:
            flags.append(f"account {line['account']} not in {e['entity']} chart or TB")
        if "memo" in line and len(line["memo"]) > 60:
            flags.append("free-text memo addressed to automated reviewers")
    if flags:
        print(e["id"], e["entity"], e["date"], e["description"][:45], "|", "; ".join(flags))
sig = {}
for e in je:
    key = (e["entity"], e["date"], tuple((line["account"], line["debit"], line["credit"]) for line in e["lines"]))
    sig.setdefault(key, []).append(e["id"])
print("duplicate postings:", [v for v in sig.values() if len(v) > 1])

