"""Consolidated balances, and the balance sheet, profit and loss and changes in equity built from them."""
from dataclasses import dataclass
from decimal import Decimal

from app.domain.entries import Entry, Posting
from app.domain.ledger import CoaAccount


def balances_by_account(translated: list[Posting], eliminations: list[Entry], coa: dict[str, CoaAccount]) -> dict[str, Decimal]:
    """Debit-positive GBP balance per group account. Equity legs of eliminations are left out: consolidated equity is
    built from the prior-year file and the reserve, not from translating each entity's own equity."""
    totals: dict[str, Decimal] = {}
    legs = list(translated) + [leg for entry in eliminations for leg in entry.lines]
    for p in legs:
        account = coa.get(p.account)
        if account is not None and account.account_type == "Equity":
            continue
        totals[p.account] = totals.get(p.account, Decimal(0)) + p.amount
    return totals


def _of_type(balances: dict[str, Decimal], coa: dict[str, CoaAccount], statement: str) -> Decimal:
    return sum((v for k, v in balances.items() if k in coa and coa[k].statement == statement), Decimal(0))


def net_assets(balances: dict[str, Decimal], coa: dict[str, CoaAccount]) -> Decimal:
    """Assets less liabilities (debit-positive sum of the balance-sheet accounts). Equal to total equity."""
    return _of_type(balances, coa, "BS")


def profit(balances: dict[str, Decimal], coa: dict[str, CoaAccount]) -> Decimal:
    """Group profit for the year: the credit balance of the income-statement accounts."""
    return -_of_type(balances, coa, "PL")


def revenue(balances: dict[str, Decimal], coa: dict[str, CoaAccount]) -> Decimal:
    return -sum((v for k, v in balances.items() if k in coa and coa[k].account_type == "Revenue"), Decimal(0))


def total_assets(balances: dict[str, Decimal], coa: dict[str, CoaAccount]) -> Decimal:
    return sum((v for k, v in balances.items() if k in coa and coa[k].account_type == "Asset"), Decimal(0))


@dataclass(frozen=True)
class EquityView:
    """The equity side as numbers: opening, the year's movements, closing. NCI profit is shown inside NCI."""

    share_capital: Decimal
    retained_opening: Decimal
    reserve_opening: Decimal
    nci_opening: Decimal
    owners_profit: Decimal
    nci_acquired: Decimal
    nci_profit: Decimal
    nci_translation: Decimal
    reserve_movement: Decimal


def balance_sheet(balances: dict[str, Decimal], coa: dict[str, CoaAccount], equity: EquityView) -> dict[str, object]:
    def section(kind: str, sign: int) -> list[dict[str, object]]:
        rows = [(code, balances[code]) for code in sorted(balances) if code in coa and coa[code].account_type == kind]
        return [{"account": c, "name": coa[c].name, "amount_gbp": sign * v} for c, v in rows if v != 0]

    assets, liabilities = section("Asset", 1), section("Liability", -1)
    reserve = equity.reserve_opening + equity.reserve_movement
    nci = equity.nci_opening + equity.nci_acquired + equity.nci_profit + equity.nci_translation
    retained = equity.retained_opening + equity.owners_profit
    lines = [("3100", "Share capital", equity.share_capital), ("3200", "Retained earnings", retained),
             ("3300", "Translation reserve", reserve), ("3400", "Non-controlling interest", nci)]
    return {
        "currency": "GBP", "as_of": "2024-12-31",
        "assets": assets, "total_assets": total_assets(balances, coa),
        "liabilities": liabilities, "total_liabilities": -sum((r["amount_gbp"] for r in section("Liability", 1)), Decimal(0)),  # type: ignore[misc]
        "equity": [{"account": c, "name": n, "amount_gbp": v} for c, n, v in lines],
        "total_equity": sum((v for _, _, v in lines), Decimal(0)),
    }


def profit_and_loss(balances: dict[str, Decimal], coa: dict[str, CoaAccount], owners: Decimal, nci: Decimal) -> dict[str, object]:
    def rows(kind: str, sign: int) -> list[dict[str, object]]:
        return [{"account": c, "name": coa[c].name, "amount_gbp": sign * balances[c]}
                for c in sorted(balances) if c in coa and coa[c].account_type == kind and balances[c] != 0]

    income, costs = rows("Revenue", -1), rows("Expense", 1)
    return {
        "currency": "GBP", "period": "2024-01-01 to 2024-12-31",
        "revenue": income, "total_revenue": revenue(balances, coa),
        "expenses": costs, "total_expenses": sum((r["amount_gbp"] for r in costs), Decimal(0)),  # type: ignore[misc]
        "profit_for_the_year": profit(balances, coa),
        "attributable_to": {"owners_of_the_parent": owners, "non_controlling_interest": nci},
    }


def changes_in_equity(e: EquityView) -> dict[str, object]:
    def row(label: str, sc: Decimal, re: Decimal, tr: Decimal, nci: Decimal) -> dict[str, object]:
        return {"item": label, "share_capital": sc, "retained_earnings": re, "translation_reserve": tr,
                "non_controlling_interest": nci, "total": sc + re + tr + nci}

    zero = Decimal(0)
    rows = [
        row("Opening balance at 1 January 2024", e.share_capital, e.retained_opening, e.reserve_opening, e.nci_opening),
        row("Profit for the year", zero, e.owners_profit, zero, e.nci_profit),
        row("Non-controlling interest on acquisition of Northwind India", zero, zero, zero, e.nci_acquired),
        row("Exchange differences on translation", zero, zero, e.reserve_movement, e.nci_translation),
    ]
    closing = row("Closing balance at 31 December 2024", *(sum((r[k] for r in rows), zero)  # type: ignore[misc]
                  for k in ("share_capital", "retained_earnings", "translation_reserve", "non_controlling_interest")))
    return {"currency": "GBP", "period": "2024-01-01 to 2024-12-31", "rows": rows + [closing]}

